selector_to_html = {"a[href=\"#module-pyskyfire.ducts.port\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.port<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.port\" title=\"Link to this heading\">\u00b6</a></h1><p>How a collecting passage hands its flow to a pipe.</p><p>A volute and a chamber manifold both end at a flange, and both need a duct to\nget there, but they leave in different directions. A volute\u2019s flow is already\ntravelling round the passage, so its duct leaves tangentially and turns; a\nmanifold has no such direction, so its duct runs straight out of the dome its\nsection is built on, aimed wherever the packaging wants it. Those are two ports,\nnot two classes of machine, and either passage may carry either one \u2013 a\nmanifold fed tangentially is a real arrangement, and it should not cost a second\nimplementation of the same duct.</p>", "a[href=\"DomeSite.html#pyskyfire.ducts.port.DomeSite\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.DomeSite\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DomeSite</span></span></dt><dd><p>The half-ellipse a stub leaves through, in machine coordinates.</p><p>The ellipse is the one the passage\u2019s own section is built on, centred where\nits two axes cross, which is the point a stub is aimed from. Only part of it\nis passage boundary: past <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">arc_limit</span></code> the section\u2019s fillets have taken\nover and the ellipse runs outboard of the metal, so a stub aimed out there\nwould leave through the side rather than the dome.</p></dd>", "a[href=\"Port.html#pyskyfire.ducts.port.Port\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.Port\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Port</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>A request for the duct carrying collected flow to its flange.</p></dd>", "a[href=\"RadialPort.html#pyskyfire.ducts.port.RadialPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.RadialPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RadialPort</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Port</span></code></p><p>A straight stub leaving the dome a manifold\u2019s section is built on.</p><p>This is the chamber-manifold outlet. There is no swirl to take off\ntangentially, so the duct runs straight from the dome to its flange. It is\naimed from the ellipse centre \u2013 where the section\u2019s two axes cross, which\nis a defined point in a way the curved surface is not \u2013 and steered by a\nsingle angle in the section\u2019s own plane.</p><p class=\"rubric\">Notes</p><p>The angle both aims the stub and sizes it. How much room the dome leaves\nacross a tilted stub is not the ellipse\u2019s own semi-axis: it is how far the\npart of the ellipse that is actually passage boundary reaches across the\ndirection chosen, which closes down as the stub turns toward the fillets.\nThe stub stays centred on the ray it was aimed along, so a tilted one is\nsized by whichever side of it runs out of dome first; letting it shift off\nthat ray to take the room on the other side is a further freedom, not taken\nhere.</p></dd>", "a[href=\"PortSite.html#pyskyfire.ducts.port.PortSite\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.PortSite\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PortSite</span></span></dt><dd><p>What a passage knows about where its port attaches.</p></dd>", "a[href=\"ResolvedRadialPort.html#pyskyfire.ducts.port.ResolvedRadialPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedRadialPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResolvedRadialPort</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ResolvedPort</span></code></p><p>A stub placed in machine coordinates, with the dome it leaves through.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"ResolvedPort.html#pyskyfire.ducts.port.ResolvedPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResolvedPort</span></span></dt><dd><p>A duct placed in machine coordinates.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
